// 037: parse an SVG path of M/H/V/L commands into subpaths and report diagonal segments.
function stepShape037(d){const paths=[],diagonal=[];let cur=null,x=0,y=0;for(const m of d.matchAll(/([MHVL])\s*(-?[0-9.]+)(?:[ ,]+(-?[0-9.]+))?/g)){const [,cmd,a,b]=m;if(cmd==='M'){x=Number(a);y=Number(b);cur=[[x,y]];paths.push(cur);continue;}const px=x,py=y;if(cmd==='H')x=Number(a);else if(cmd==='V')y=Number(a);else{x=Number(a);y=Number(b);}if(Math.abs(px-x)>.011&&Math.abs(py-y)>.011)diagonal.push([[px,py],[x,y]]);cur.push([x,y]);}return {paths,diagonal};}
