// Observe completion independently of language/layout/history checks. A previous
// report must never satisfy the wait for a newly started inspection.
async function observePractice(read,previous,started){
 const end=Date.now()+45000;
 while(Date.now()<end){
  let value;try{value=await read();}catch(error){if(!/Execution context was destroyed|Cannot find context|navigation/i.test(error.message))throw error;}
  const report=value?.report,key=report&&(report.id||report.started);
  if(value&&!value.busy&&key&&key!==previous&&Number.isFinite(Date.parse(report.finished))&&Date.parse(report.finished)>Date.parse(report.started))return {report,elapsedMs:Date.now()-started};
  await new Promise(r=>setTimeout(r,50));
 }
 throw Error('No fresh completed practice report within 45 seconds');
}
